/* Demonstrates using timer_getoverrun(2) by intentionally blocking the notification signal to induce an overrun. */
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define CLOCKID CLOCK_REALTIME
#define TIMER_SIG SIGRTMIN

timer_t global_timerid;

void handler(int sig, siginfo_t *si, void *uc) {
    if (si->si_code == SI_TIMER) {
        // Check if the timer ID matches (for robustness)
        if (si->si_value.sival_ptr == &global_timerid) {
            int overruns = timer_getoverrun(global_timerid);

            if (overruns == -1) {
                perror("timer_getoverrun failed");
            } else {
                printf("Timer Notification Received. Overruns detected: %d\n", overruns);
            }
        }
    }
}

int main() {
    struct sigevent sev;
    struct itimerspec its;
    struct sigaction sa;

    // 1. Setup signal handler for the real-time signal
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = handler;
    sigemptyset(&sa.sa_mask);

    if (sigaction(TIMER_SIG, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // 2. Setup sigevent structure for notification
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = TIMER_SIG;
    sev.sigev_value.sival_ptr = &global_timerid; // Pass ID reference

    // 3. Create the timer
    if (timer_create(CLOCKID, &sev, &global_timerid) == -1) {
        perror("timer_create");
        return EXIT_FAILURE;
    }

    // 4. Set the timer interval (fast: 5 milliseconds)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 5000000; 
    its.it_value.tv_sec = 0; 
    its.it_value.tv_nsec = 5000000; // Initial expiration

    if (timer_settime(global_timerid, 0, &its, NULL) == -1) {
        perror("timer_settime");
        timer_delete(global_timerid);
        return EXIT_FAILURE;
    }

    printf("Timer set to expire every 5ms.\n");

    // 5. Block the signal for 1 second to force many overruns (200 expected ticks)
    sigset_t mask, oldmask;
    sigemptyset(&mask);
    sigaddset(&mask, TIMER_SIG);
    if (sigprocmask(SIG_BLOCK, &mask, &oldmask) == -1) {
        perror("sigprocmask block");
        return EXIT_FAILURE;
    }

    printf("Blocking signal for 1 second. Timer ticks accumulate.\n");
    sleep(1);

    // 6. Unblock the signal. The pending notification is delivered, allowing the handler to run.
    printf("Unblocking signal. Handler will run and report overruns.\n");
    if (sigprocmask(SIG_SETMASK, &oldmask, NULL) == -1) {
        perror("sigprocmask unblock");
        return EXIT_FAILURE;
    }

    sleep(1); // Wait for the final signal delivery

    // Cleanup
    timer_delete(global_timerid);
    return EXIT_SUCCESS;
}
